'use strict';
const state={token:localStorage.getItem('nova_token')||'',language:localStorage.getItem('nova_language')||'en',user:null,chats:[],active:null,messages:new Map(),ws:null,typingTimer:null,search:'',pendingReply:null,call:null,pendingIncoming:null,notificationAudio:null,audioUnlocked:false,ringTimer:null,notificationPermissionAsked:false};
const $=s=>document.querySelector(s); const app=$('#app');
const I18N={en:{lang:'English',username:'Username',password:'Password',nickname:'your nickname',passwordHint:'minimum 6 characters',signIn:'Sign in',create:'Create account',language:'Messenger language',messages:'Messages, voice calls and video calls in your browser.',search:'Search people or messages...',newChat:'New chat',profile:'Profile',select:'Select a chat',sub:'Your conversations will appear here',call:'Call',video:'Video',theme:'Theme',logout:'Log out',write:'Write a message...',send:'Send',addFile:'Add file',welcome:'Welcome to Nova',start:'Start a conversation and try a call.',site:'Learn about Nova Messenger →',newConversation:'New conversation',searchUsername:'Search username...',close:'Close'},uk:{lang:'Українська',username:'Імʼя користувача',password:'Пароль',nickname:'ваш нікнейм',passwordHint:'мінімум 6 символів',signIn:'Увійти',create:'Створити акаунт',language:'Мова месенджера',messages:'Повідомлення, голосові та відеодзвінки у браузері.',search:'Пошук людей або повідомлень...',newChat:'Новий чат',profile:'Профіль',select:'Оберіть чат',sub:'Ваші розмови зʼявляться тут',call:'Дзвінок',video:'Відео',theme:'Тема',logout:'Вийти',write:'Написати повідомлення...',send:'Надіслати',addFile:'Додати файл',welcome:'Ласкаво просимо до Nova',start:'Почніть розмову та спробуйте дзвінок.',site:'Дізнатися про Nova Messenger →',newConversation:'Нова розмова',searchUsername:'Пошук за іменем...',close:'Закрити'},ru:{lang:'Русский',username:'Имя пользователя',password:'Пароль',nickname:'ваш никнейм',passwordHint:'минимум 6 символов',signIn:'Войти',create:'Создать аккаунт',language:'Язык мессенджера',messages:'Сообщения, голосовые и видеозвонки в браузере.',search:'Поиск людей или сообщений...',newChat:'Новый чат',profile:'Профиль',select:'Выберите чат',sub:'Ваши разговоры появятся здесь',call:'Звонок',video:'Видео',theme:'Тема',logout:'Выйти',write:'Написать сообщение...',send:'Отправить',addFile:'Добавить файл',welcome:'Добро пожаловать в Nova',start:'Начните разговор и попробуйте звонок.',site:'Узнать о Nova Messenger →',newConversation:'Новый разговор',searchUsername:'Поиск по нику...',close:'Закрыть'}};
const t=k=>(I18N[state.language]||I18N.en)[k]||I18N.en[k]||k;

async function api(url,options={}){const headers={'Content-Type':'application/json',...(options.headers||{})};if(state.token)headers.Authorization='Bearer '+state.token;const r=await fetch(url,{...options,headers});let data={};try{data=await r.json()}catch{}if(!r.ok)throw new Error(data.error||'Request failed');return data}
function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function initials(u){return esc((u.displayName||u.username||'?').slice(0,1).toUpperCase())}
function avatar(u,size=''){if(u?.avatar)return `<div class="avatar ${size}"><img src="${esc(u.avatar)}"></div>`;return `<div class="avatar ${size}">${initials(u||{})}</div>`}
function fmt(ts){return new Date(ts).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}
function renderLogin(error=''){app.innerHTML=`<div class="login"><div class="card login-card"><img class="login-logo" src="/nova-logo.svg" alt="Nova Messenger"><h1>Nova Messenger</h1><p class="muted">${t('messages')}</p>${error?`<div class="notice">${esc(error)}</div>`:''}<div class="field"><label>${t('username')}</label><input id="loginUser" autocomplete="username" placeholder="${t('nickname')}"></div><div class="field"><label>${t('password')}</label><input id="loginPass" type="password" autocomplete="current-password" placeholder="${t('passwordHint')}"></div><div class="field language-field"><label>${t('language')}</label><select id="languageSelect"><option value="en">English</option><option value="uk">Українська</option><option value="ru">Русский</option></select></div><div class="row"><button class="primary" id="loginBtn">${t('signIn')}</button><button class="secondary" id="registerBtn">${t('create')}</button></div><a class="site-link" href="/site">${t('site')}</a></div></div>`;$('#languageSelect').value=state.language;$('#languageSelect').onchange=e=>{state.language=e.target.value;localStorage.setItem('nova_language',state.language);renderLogin(error)};$('#loginBtn').onclick=()=>login(false);$('#registerBtn').onclick=()=>login(true)}
async function login(register){const username=$('#loginUser').value;const password=$('#loginPass').value;try{const data=await api(register?'/api/auth/register':'/api/auth/login',{method:'POST',body:JSON.stringify({username,password,displayName:username,language:state.language})});state.token=data.token;state.user=data.user;state.language=data.user?.language||state.language;localStorage.setItem('nova_token',state.token);localStorage.setItem('nova_language',state.language);await boot()}catch(e){renderLogin(e.message)}}
function renderShell(){app.innerHTML=`<div class="shell"><aside class="sidebar" id="sidebar"><div class="brand"><img class="brand-logo" src="/nova-logo.svg" alt="Nova"><div><b>Nova</b><span>Messenger</span></div></div><div class="search"><input id="search" placeholder="${t('search')}"></div><div class="toolbar side-actions"><button class="secondary" id="newChat">${t('newChat')}</button><button class="secondary" id="profileBtn">${t('profile')}</button></div><div class="chat-list" id="chatList"></div><a class="sidebar-site" href="/site">Nova website</a></aside><main class="main"><header class="topbar"><div id="chatHeader"><div class="top-title">${t('select')}</div><div class="top-sub">${t('sub')}</div></div><div class="top-actions"><div class="call-actions hide" id="callActions"><button class="icon-btn" id="voiceCall" title="Voice call">${t('call')}</button><button class="icon-btn" id="videoCall" title="Video call">${t('video')}</button></div><div class="toolbar"><button class="secondary" id="themeBtn">${t('theme')}</button><button class="secondary" id="logoutBtn">${t('logout')}</button></div></div></header><section class="messages" id="messages"><div class="empty"><img class="empty-logo" src="/nova-logo.svg" alt="Nova"><h2>${t('welcome')}</h2><p>${t('start')}</p></div></section><div class="typing" id="typing"></div><form class="composer hide" id="composer"><button class="attach-btn" id="attachBtn" type="button" title="${t('addFile')}">+</button><input id="fileInput" type="file" hidden><div class="composer-main"><div class="attachment-preview hide" id="attachmentPreview"></div><textarea id="composerText" placeholder="${t('write')}"></textarea></div><button class="primary" type="submit">${t('send')}</button></form></main></div>`;$('#logoutBtn').onclick=logout;$('#newChat').onclick=showPeople;$('#profileBtn').onclick=showProfile;$('#themeBtn').onclick=toggleTheme;$('#search').oninput=e=>searchAll(e.target.value);$('#composer').onsubmit=e=>{e.preventDefault();sendMessage()};$('#composerText').oninput=typing;$('#composerText').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&matchMedia('(min-width: 769px)').matches){e.preventDefault();sendMessage()}};$('#attachBtn').onclick=()=>$('#fileInput').click();$('#fileInput').onchange=handleFileSelect}
function renderChats(){const el=$('#chatList');el.innerHTML=state.chats.map(c=>{const other=c.members.find(m=>m.id!==state.user.id)||state.user;const unread=Number(c.unreadCount||0);return `<div class="chat ${state.active===c.id?'active':''}" data-id="${c.id}">${avatar(other)}<div class="chat-info"><div class="chat-name"><span>${esc(other.displayName)}${other.online?'<i class="online"></i>':''}</span><span>${c.lastMessage?fmt(c.lastMessage.createdAt):''}</span></div><div class="chat-preview">${c.lastMessage?esc(c.lastMessage.body):'No messages yet'}${unread?` <b class="unread-badge">${unread>99?'99+':unread}</b>`:''}</div></div></div>`}).join('');el.querySelectorAll('.chat').forEach(x=>x.onclick=()=>openChat(Number(x.dataset.id)))}
function otherForChat(c){return c?.members.find(m=>m.id!==state.user.id)||state.user}
async function openChat(id){state.active=id;const chat=state.chats.find(x=>x.id===id);if(chat){chat.unreadCount=0}renderChats();const c=chat;if(!c)return;const other=otherForChat(c);$('#chatHeader').innerHTML=`<div class="top-user">${avatar(other)}<div><div class="top-title">${esc(other.displayName)}</div><div class="top-sub">@${esc(other.username)} ${other.online?'<span class="online"></span>':'offline'}</div></div></div>`;$('#callActions').classList.remove('hide');$('#voiceCall').onclick=()=>startCall('audio');$('#videoCall').onclick=()=>startCall('video');$('#composer').classList.remove('hide');clearAttachment();$('#messages').innerHTML='';state.messages.set(id,[]);try{const data=await api('/api/chats/'+id+'/messages');state.messages.set(id,data.messages);renderMessages();if(data.messages.length)markRead(data.messages[data.messages.length-1].id)}catch(e){$('#messages').innerHTML=`<div class="notice">${esc(e.message)}</div>`}}
function renderMessages(){const list=state.messages.get(state.active)||[];const el=$('#messages');el.innerHTML=list.length?list.map(messageHtml).join(''):`<div class="empty">No messages yet. Say hello.</div>`;el.scrollTop=el.scrollHeight;el.querySelectorAll('[data-message]').forEach(node=>node.oncontextmenu=e=>{e.preventDefault();messageMenu(e,node)})}
function messageHtml(m){const mine=m.senderId===state.user.id;return `<div class="bubble-row ${mine?'mine':''}" data-message="${m.id}"><div class="bubble"><div class="body">${esc(m.body)}</div>${m.attachment?`<div style="margin-top:8px"><a href="${esc(m.attachment.data)}" download="${esc(m.attachment.name)}" style="color:inherit">Attachment: ${esc(m.attachment.name)}</a></div>`:''}<div class="meta">${fmt(m.createdAt)}${m.editedAt?' · edited':''}</div>${m.reactions?.length?`<div class="reaction-line">${m.reactions.map(r=>`<span class="reaction">${esc(r.emoji)} ${r.count}</span>`).join('')}</div>`:''}</div></div>`}
function messageMenu(e,node){const id=Number(node.dataset.message);const m=(state.messages.get(state.active)||[]).find(x=>x.id===id);if(!m)return;const menu=document.createElement('div');menu.className='context';menu.style.left=Math.min(e.clientX,innerWidth-170)+'px';menu.style.top=Math.min(e.clientY,innerHeight-180)+'px';menu.innerHTML=`<button data-a="reply">Reply</button><button data-a="react">React</button>${m.senderId===state.user.id&&!m.deleted?'<button data-a="edit">Edit</button><button data-a="delete">Delete</button>':''}`;document.body.appendChild(menu);menu.querySelectorAll('button').forEach(b=>b.onclick=async()=>{const a=b.dataset.a;menu.remove();if(a==='reply'){state.pendingReply=id;$('#composerText').focus()}if(a==='react')await react(id,'Like');if(a==='edit'){const body=prompt('Edit message',m.body);if(body!==null)await api('/api/messages/'+id,{method:'PATCH',body:JSON.stringify({body})})}if(a==='delete')await api('/api/messages/'+id,{method:'DELETE'})});setTimeout(()=>document.addEventListener('click',()=>menu.remove(),{once:true}),0)}
let selectedAttachment=null;function clearAttachment(){selectedAttachment=null;const input=$('#fileInput');const preview=$('#attachmentPreview');if(input)input.value='';if(preview){preview.classList.add('hide');preview.textContent=''}}function handleFileSelect(e){const file=e.target.files?.[0];if(!file)return;if(file.size>8*1024*1024){alert('File is too large. Maximum size is 8 MB.');clearAttachment();return}const reader=new FileReader();reader.onload=()=>{selectedAttachment={name:file.name,type:file.type||'application/octet-stream',data:reader.result};const preview=$('#attachmentPreview');if(preview){preview.textContent=`${file.name} · ${(file.size/1024/1024).toFixed(2)} MB`;preview.classList.remove('hide')}};reader.readAsDataURL(file)}async function sendMessage(){if(!state.active)return;const input=$('#composerText');const body=input.value.trim();if(!body&&!selectedAttachment)return;input.value='';const attachment=selectedAttachment;clearAttachment();try{await api('/api/chats/'+state.active+'/messages',{method:'POST',body:JSON.stringify({body,replyTo:state.pendingReply,attachment})});state.pendingReply=null}catch(e){alert(e.message)}}
async function react(id,emoji){try{await api('/api/messages/'+id+'/reactions',{method:'POST',body:JSON.stringify({emoji})})}catch(e){console.error(e)}}
async function markRead(id){if(!state.active)return;const c=state.chats.find(x=>x.id===state.active);if(c){c.lastReadId=id;c.unreadCount=0;renderChats()}try{await api('/api/chats/'+state.active+'/read',{method:'POST',body:JSON.stringify({messageId:id})})}catch{}}
function typing(){if(!state.ws||!state.active)return;state.ws.send(JSON.stringify({type:'typing',conversationId:state.active,active:true}));clearTimeout(state.typingTimer);state.typingTimer=setTimeout(()=>state.ws?.send(JSON.stringify({type:'typing',conversationId:state.active,active:false})),900)}
function connectWS(){if(!state.token)return;const proto=location.protocol==='https:'?'wss':'ws';state.ws=new WebSocket(`${proto}://${location.host}/ws?token=${encodeURIComponent(state.token)}`);state.ws.onmessage=e=>{try{handleEvent(JSON.parse(e.data))}catch(err){console.error(err)}};state.ws.onclose=()=>{if(state.token)setTimeout(connectWS,1500)}}
function sendSignal(type,payload){if(state.ws?.readyState===1)state.ws.send(JSON.stringify({type,...payload}))}
let toastTimer=null;
function unlockAudio(){if(state.audioUnlocked)return;try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;const ctx=new AC();ctx.resume();state.notificationAudio=ctx;state.audioUnlocked=true}catch{}}
function playTone(kind='message'){try{unlockAudio();const ctx=state.notificationAudio;if(!ctx)return;const osc=ctx.createOscillator();const gain=ctx.createGain();osc.type='sine';const now=ctx.currentTime;const freq=kind==='call'?520:740;osc.frequency.setValueAtTime(freq,now);osc.frequency.exponentialRampToValueAtTime(kind==='call'?660:980,now+0.09);gain.gain.setValueAtTime(0.0001,now);gain.gain.exponentialRampToValueAtTime(kind==='call'?0.12:0.07,now+0.015);gain.gain.exponentialRampToValueAtTime(0.0001,now+0.18);osc.connect(gain).connect(ctx.destination);osc.start(now);osc.stop(now+0.2)}catch{}}
function startRingtone(){stopRingtone();playTone('call');state.ringTimer=setInterval(()=>playTone('call'),900)}
function stopRingtone(){if(state.ringTimer){clearInterval(state.ringTimer);state.ringTimer=null}}
function showToast(title,text){let el=document.querySelector('#novaToast');if(!el){el=document.createElement('div');el.id='novaToast';el.className='nova-toast';document.body.appendChild(el)}el.innerHTML=`<b>${esc(title)}</b><span>${esc(text)}</span>`;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4200)}
function notifyIncomingMessage(message){if(message.senderId===state.user?.id)return;const name=message.sender?.displayName||message.sender?.username||'New message';const text=message.body||'Attachment';playTone('message');showToast(name,text);if('Notification' in window&&Notification.permission==='granted'){try{new Notification(name,{body:text,icon:'/nova-logo.svg',tag:'nova-message-'+message.conversationId})}catch{}}}
async function requestNotifications(){if(state.notificationPermissionAsked)return;state.notificationPermissionAsked=true;if('Notification' in window&&Notification.permission==='default'){try{await Notification.requestPermission()}catch{}}}
document.addEventListener('pointerdown',()=>{unlockAudio();if(state.user)requestNotifications()},{once:false});

function handleEvent(e){if(e.type==='message:new'){const id=e.message.conversationId;const list=state.messages.get(id)||[];if(!list.some(m=>m.id===e.message.id)){list.push(e.message);state.messages.set(id,list)}let c=state.chats.find(x=>x.id===id);const incoming=e.message.senderId!==state.user.id;const isActive=state.active===id;if(c){c.lastMessage=e.message;c.updatedAt=e.message.createdAt;if(incoming&&!isActive)c.unreadCount=Number(c.unreadCount||0)+1}else if(incoming){refreshChats().then(()=>{const fresh=state.chats.find(x=>x.id===id);if(fresh){fresh.unreadCount=Math.max(1,Number(fresh.unreadCount||1));renderChats()}notifyIncomingMessage(e.message)}).catch(()=>notifyIncomingMessage(e.message));return}renderChats();if(incoming&&!isActive)notifyIncomingMessage(e.message);if(isActive){renderMessages();markRead(e.message.id)}}else if(e.type==='message:update'){const list=state.messages.get(e.message.conversationId)||[];const i=list.findIndex(m=>m.id===e.message.id);if(i>=0)list[i]=e.message;state.messages.set(e.message.conversationId,list);if(state.active===e.message.conversationId)renderMessages();renderChats()}else if(e.type==='message:reactions'){const list=state.messages.get(state.active)||[];const m=list.find(x=>x.id===e.messageId);if(m)m.reactions=e.reactions;if(state.active)renderMessages()}else if(e.type==='typing'&&e.conversationId===state.active&&e.userId!==state.user.id){const c=state.chats.find(x=>x.id===state.active);const u=c?.members.find(m=>m.id===e.userId);$('#typing').textContent=e.active?`${u?.displayName||'Someone'} is typing…`:''}else if(e.type==='profile:update'){const i=state.chats.flatMap(c=>c.members).find(m=>m.id===e.user.id);if(i)Object.assign(i,e.user);renderChats()}else if(e.type.startsWith('call:'))handleCallEvent(e)}
async function boot(){try{const me=await api('/api/me');state.user=me.user;state.language=me.user?.language||state.language;localStorage.setItem('nova_language',state.language);renderShell();const data=await api('/api/chats');state.chats=data.conversations;renderChats();connectWS()}catch(e){state.token='';try{localStorage.removeItem('nova_token')}catch{};renderLogin(e.message)}}
async function logout(){if(state.call)endCall(false);try{await api('/api/auth/logout',{method:'POST'})}catch{}state.token='';localStorage.removeItem('nova_token');state.ws?.close();renderLogin()}
function showPeople(){const modal=document.createElement('div');modal.className='modal';modal.innerHTML=`<div class="card"><h2>${t('newConversation')}</h2><div class="field"><input id="personSearch" placeholder="${t('searchUsername')}" autocomplete="off"></div><div id="people"></div><button class="secondary" id="close">${t('close')}</button></div>`;document.body.appendChild(modal);$('#close').onclick=()=>modal.remove();const search=$('#personSearch');search.focus();search.oninput=async e=>{const q=e.target.value.trim();const people=$('#people');if(!q){people.innerHTML='';return}try{const data=await api('/api/users/search?q='+encodeURIComponent(q));people.innerHTML=(data.users||[]).map(u=>`<button type="button" class="user-result" data-user="${u.id}">${avatar(u)}<div style="flex:1;text-align:left"><b>${esc(u.displayName)}</b><div class="muted">@${esc(u.username)} ${u.online?'· online':''}</div></div></button>`).join('')||'<div class="muted" style="padding:12px">No users found</div>';people.querySelectorAll('.user-result').forEach(node=>node.onclick=()=>startDirectChat(Number(node.dataset.user),modal,node))}catch(err){people.innerHTML=`<div class="notice">${esc(err.message)}</div>`}}}
async function startDirectChat(userId,modal,node){node.disabled=true;try{const d=await api('/api/chats/direct',{method:'POST',body:JSON.stringify({userId})});await refreshChats();modal.remove();await openChat(d.conversation.id)}catch(e){node.disabled=false;alert('Не удалось открыть чат: '+e.message)}}
function showProfile(){const u=state.user;const modal=document.createElement('div');modal.className='modal';modal.innerHTML=`<div class="card"><h2>Your profile</h2><div class="field"><label>Display name</label><input id="pName" value="${esc(u.displayName)}"></div><div class="field"><label>Bio</label><textarea id="pBio">${esc(u.bio)}</textarea></div><div class="field"><label>Avatar URL</label><input id="pAvatar" value="${esc(u.avatar)}"></div><div class="row"><button class="primary" id="saveP">Save</button><button class="secondary" id="closeP">Cancel</button></div></div>`;document.body.appendChild(modal);$('#closeP').onclick=()=>modal.remove();$('#saveP').onclick=async()=>{try{const d=await api('/api/me',{method:'PATCH',body:JSON.stringify({displayName:$('#pName').value,bio:$('#pBio').value,avatar:$('#pAvatar').value})});state.user=d.user;modal.remove();renderChats()}catch(e){alert(e.message)}}}
async function refreshChats(){const data=await api('/api/chats');state.chats=data.conversations;renderChats()}
let searchTimer=null;async function searchAll(q){const value=q.trim();if(value.length<2)return;clearTimeout(searchTimer);searchTimer=setTimeout(async()=>{try{const [usersData,messagesData]=await Promise.all([api('/api/users/search?q='+encodeURIComponent(value)),api('/api/search/messages?q='+encodeURIComponent(value))]);const el=$('#messages');const people=(usersData.users||[]).map(u=>`<div class="search-person" data-user="${u.id}">${avatar(u)}<div><b>${esc(u.displayName)}</b><div class="muted">@${esc(u.username)} ${u.online?'· online':''}</div></div></div>`).join('');const msgs=(messagesData.messages||[]).map(messageHtml).join('');el.innerHTML=(people?`<div class="search-section"><h3>People</h3>${people}</div>`:'')+(msgs?`<div class="search-section"><h3>Messages</h3>${msgs}</div>`:'')||'<div class="empty">Nothing found.</div>';el.querySelectorAll('.search-person').forEach(node=>node.onclick=async()=>{try{const d=await api('/api/chats/direct',{method:'POST',body:JSON.stringify({userId:Number(node.dataset.user)})});await refreshChats();$('#search').value='';await openChat(d.conversation.id)}catch(e){alert(e.message)}})}catch(e){console.error(e)}},150)}
function toggleTheme(){document.documentElement.classList.toggle('light');if(document.documentElement.classList.contains('light')){document.documentElement.style.setProperty('--bg','#f3f6fb');document.documentElement.style.setProperty('--panel','#fff');document.documentElement.style.setProperty('--panel2','#eef2f8');document.documentElement.style.setProperty('--text','#152033');document.documentElement.style.setProperty('--muted','#647188');document.documentElement.style.setProperty('--line','#dce3ee');document.documentElement.style.setProperty('--bubble','#eef2f8');document.documentElement.style.setProperty('--mine','#d9e7ff')}else{location.reload()}}

function callOther(){const c=state.chats.find(x=>x.id===state.active);return otherForChat(c)}
async function startCall(mode){if(!state.active||state.call)return;const other=callOther();if(!other||other.id===state.user.id)return;const call={id:crypto.randomUUID(),mode,role:'caller',peerId:other.id,conversationId:state.active,pc:null,local:null,remote:null,iceQueue:[]};state.call=call;try{call.local=await navigator.mediaDevices.getUserMedia({audio:true,video:mode==='video'});createPeer(call);showCallPanel('outgoing',other);const offer=await call.pc.createOffer();await call.pc.setLocalDescription(offer);sendSignal('call:invite',{toUserId:other.id,conversationId:state.active,callId:call.id,mode,description:call.pc.localDescription})}catch(e){console.error(e);cleanupCall();alert('Не удалось начать звонок. Разреши доступ к микрофону/камере в браузере.')}}
function createPeer(call){call.pc=new RTCPeerConnection({iceServers:[{urls:'stun:stun.l.google.com:19302'}]});call.local.getTracks().forEach(t=>call.pc.addTrack(t,call.local));call.pc.onicecandidate=e=>{if(e.candidate)sendSignal('call:ice',{toUserId:call.peerId,conversationId:call.conversationId,callId:call.id,candidate:e.candidate})};call.pc.ontrack=e=>{call.remote=e.streams[0];const v=$('#remoteVideo');if(v){v.srcObject=e.streams[0];v.play?.().catch(()=>{})}};call.pc.onconnectionstatechange=()=>{if(['failed','disconnected','closed'].includes(call.pc.connectionState))endCall(false)}}
function showCallPanel(kind,other){removeCallPanel();const modal=document.createElement('div');modal.className='call-modal';modal.id='callPanel';const video=state.call?.mode==='video';modal.innerHTML=`<div class="call-card ${video?'video-call':''}"><div class="call-head"><div>${avatar(other,'call-avatar')}<div><b>${esc(other.displayName)}</b><span>${kind==='incoming'?'Incoming':'Calling'} ${video?'video':'voice'} call</span></div></div><button class="secondary" id="callClose">×</button></div><div class="call-stage">${video?'<video id="remoteVideo" autoplay playsinline></video><video id="localVideo" autoplay muted playsinline></video>':'<div class="voice-stage">'+avatar(other,'call-big-avatar')+'<div class="call-status">'+(kind==='incoming'?'Incoming call…':kind==='outgoing'?'Ringing…':'Connected')+'</div></div>'}</div><div class="call-controls">${kind==='incoming'?'<button class="call-accept" id="acceptCall">Accept</button><button class="call-reject" id="rejectCall">Decline</button>':'<button class="call-control" id="muteCall">Mute</button><button class="call-end" id="endCallBtn">End call</button>'}</div></div>`;document.body.appendChild(modal);$('#callClose').onclick=()=>kind==='incoming'?rejectIncoming():endCall(true);if(kind==='incoming'){$('#acceptCall').onclick=()=>acceptIncoming();$('#rejectCall').onclick=rejectIncoming}else{$('#muteCall').onclick=toggleMute;$('#endCallBtn').onclick=()=>endCall(true);if(video){const lv=$('#localVideo');lv.srcObject=state.call?.local;lv.play?.().catch(()=>{})}}}
function removeCallPanel(){$('#callPanel')?.remove()}
async function handleCallEvent(e){if(e.type==='call:invite'){startRingtone();if(state.call){sendSignal('call:reject',{toUserId:e.fromUserId,conversationId:e.conversationId,callId:e.callId,reason:'busy'});return}state.pendingIncoming=e;showIncoming(e)}else if(e.type==='call:offer'){if(!state.call||state.call.id!==e.callId)return;state.call.remoteOffer=e.description;if(state.call.role==='callee'&&state.call.pc){await state.call.pc.setRemoteDescription(e.description);for(const c of state.call.iceQueue)await state.call.pc.addIceCandidate(c).catch(()=>{});state.call.iceQueue=[];const answer=await state.call.pc.createAnswer();await state.call.pc.setLocalDescription(answer);sendSignal('call:answer',{toUserId:state.call.peerId,conversationId:state.call.conversationId,callId:state.call.id,description:answer})}}else if(e.type==='call:answer'){if(state.call?.id!==e.callId)return;await state.call.pc.setRemoteDescription(e.description);await flushIce()}else if(e.type==='call:ice'){if(state.call?.id!==e.callId)return;if(state.call.pc?.remoteDescription)await state.call.pc.addIceCandidate(e.candidate).catch(()=>{});else state.call.iceQueue.push(e.candidate)}else if(e.type==='call:end'||e.type==='call:reject'){if(state.call?.id===e.callId){cleanupCall();if(e.type==='call:reject')alert('Call declined'+(e.reason?' ('+e.reason+')':''))}else if(state.pendingIncoming?.callId===e.callId){state.pendingIncoming=null;removeCallPanel()}}}
function showIncoming(e){const other=e.fromUser||callOther();state.pendingIncoming=e;const modal=document.createElement('div');modal.className='call-modal';modal.id='callPanel';modal.innerHTML=`<div class="call-card incoming-call"><div class="incoming-avatar">${avatar(other,'call-big-avatar')}</div><h2>${esc(other.displayName)}</h2><p>${e.mode==='video'?'Video':'Voice'} call</p><div class="incoming-actions"><button class="call-accept" id="acceptCall">Accept</button><button class="call-reject" id="rejectCall">Decline</button></div></div>`;document.body.appendChild(modal);$('#acceptCall').onclick=acceptIncoming;$('#rejectCall').onclick=rejectIncoming}
async function acceptIncoming(){stopRingtone();const e=state.pendingIncoming;if(!e)return;state.pendingIncoming=null;const call={id:e.callId,mode:e.mode,role:'callee',peerId:e.fromUserId,conversationId:e.conversationId,pc:null,local:null,remote:null,iceQueue:[]};state.call=call;try{call.local=await navigator.mediaDevices.getUserMedia({audio:true,video:e.mode==='video'});createPeer(call);await call.pc.setRemoteDescription(e.description||call.remoteOffer);await flushIce();showCallPanel('connected',e.fromUser);const answer=await call.pc.createAnswer();await call.pc.setLocalDescription(answer);sendSignal('call:answer',{toUserId:call.peerId,conversationId:call.conversationId,callId:call.id,description:answer});if(e.mode==='video'){$('#localVideo').srcObject=call.local;$('#localVideo').play?.().catch(()=>{})}}catch(err){console.error(err);sendSignal('call:reject',{toUserId:e.fromUserId,conversationId:e.conversationId,callId:e.callId,reason:'media-denied'});cleanupCall();alert('Не удалось принять звонок: разреши микрофон/камеру.')}}
async function flushIce(){if(!state.call?.pc?.remoteDescription)return;for(const c of state.call.iceQueue.splice(0))await state.call.pc.addIceCandidate(c).catch(()=>{})}
function rejectIncoming(){stopRingtone();const e=state.pendingIncoming;if(e)sendSignal('call:reject',{toUserId:e.fromUserId,conversationId:e.conversationId,callId:e.callId,reason:'declined'});state.pendingIncoming=null;removeCallPanel()}
function toggleMute(){const t=state.call?.local?.getAudioTracks?.()[0];if(!t)return;t.enabled=!t.enabled;$('#muteCall').textContent=t.enabled?'Mute':'Unmute'}
function endCall(notify=true){const c=state.call;if(notify&&c)sendSignal('call:end',{toUserId:c.peerId,conversationId:c.conversationId,callId:c.id});cleanupCall()}
function cleanupCall(){stopRingtone();const c=state.call;if(c){c.local?.getTracks().forEach(t=>t.stop());c.pc?.close()}state.call=null;state.pendingIncoming=null;removeCallPanel()}
boot();
