/* Adaptive device detection: phone / tablet / desktop */
(function NovaDeviceManager(){
  const root=document.documentElement;
  const ua=navigator.userAgent||'';
  const touch=('ontouchstart' in window)||navigator.maxTouchPoints>0;
  const coarse=window.matchMedia && window.matchMedia('(pointer: coarse)').matches;
  const width=Math.min(window.innerWidth||0,window.innerHeight||0);
  const short=Math.min(screen.width||0,screen.height||0);
  const mobileUA=/Android|webOS|iPhone|iPod|BlackBerry|IEMobile|Opera Mini|Mobile/i.test(ua);
  const tabletUA=/iPad|Tablet|Android(?!.*Mobile)/i.test(ua);
  let device='desktop';
  if(mobileUA || (touch && short<=600)) device='phone';
  else if(tabletUA || (touch && short>600 && short<=1100)) device='tablet';
  root.dataset.device=device;
  root.dataset.input=(coarse||touch)?'coarse':'fine';
  root.dataset.touch=touch?'true':'false';
  root.classList.toggle('touch-device',touch);
  function update(){
    root.dataset.orientation=(window.innerWidth>window.innerHeight)?'landscape':'portrait';
    root.style.setProperty('--vw',window.innerWidth+'px');
    root.style.setProperty('--vh',window.innerHeight+'px');
    root.style.setProperty('--dpr',window.devicePixelRatio||1);
  }
  update();
  addEventListener('resize',update,{passive:true});
  addEventListener('orientationchange',()=>setTimeout(update,100),{passive:true});
  if(window.visualViewport) window.visualViewport.addEventListener('resize',update,{passive:true});
  // Expose a small API for future UI modules.
  window.NovaDevice={get type(){return root.dataset.device},isPhone:()=>root.dataset.device==='phone',isTablet:()=>root.dataset.device==='tablet',isDesktop:()=>root.dataset.device==='desktop',isTouch:()=>root.dataset.touch==='true'};
})();
